# Generated by GitHub Copilot - Oct-05-2026
def test_projection_chunks_keep_ids_times_and_checksums(tmp_path):
    """Bounded projections preserve a deterministic path back to observed source IDs."""
    records=[{'source_record_index':index,'time':index/2,'track_id':f'T{index}'} for index in range(7)]
    index=write_indexed_projection(tmp_path,'people',iter(records),'people_observations.json',max_records=3)
    assert index['record_count']==7 and len(index['chunks'])==3
    loaded=[]
    for chunk in index['chunks']:
        path=tmp_path/chunk['path']
        assert file_hash(path)==chunk['sha256']
        loaded.extend(read_json(path)['records'])
    assert loaded==records


