def test_analysis_reference_hydration_rejects_corruption_and_traversal(tmp_path):
    """Camera-only resume cannot follow arbitrary paths or altered evidence."""
    words=[{'word_id':'W','word':'Literal.','start':0,'end':1}]
    write_json(tmp_path/'words.json',words)
    analysis={'metadata':{'duration':1},'words':words}
    document=compact_analysis_document(analysis,tmp_path)
    write_json(tmp_path/'analysis.json',document)
    assert 'words' not in document
    assert load_analysis_artifacts(tmp_path)['words']==words
    write_json(tmp_path/'words.json',[])
    with pytest.raises(ValueError,match='Checksum'):
        load_analysis_artifacts(tmp_path)
    document['collection_refs']['words']['path']='../words.json'
    write_json(tmp_path/'analysis.json',document)
    with pytest.raises(ValueError,match='insegura'):
        load_analysis_artifacts(tmp_path)


