def test_essential_over_32mb_has_equivalent_or_partial(tmp_path,monkeypatch):
    """Oversized essentials stay traceable and cannot silently disappear from a READY ZIP."""
    module=exporter_module(monkeypatch)
    analysis=tmp_path/'analysis'/'large'
    analysis.mkdir(parents=True)
    write_json(analysis/'words.json',[{'word_id':'W','word':'literal','start':0,'end':1}])
    with (analysis/'analysis.json').open('wb') as handle:
        handle.write(b'{"large_fixture":"')
        block=b'x' * 1024 ** 2
        for index in range(33):
            handle.write(block)
        handle.write(b'"}')
    _,manifest=module.build_analysis_package(tmp_path,analysis,tmp_path/'packages','without',32,250,False,0)
    assert manifest['export_state']=='PARTIAL_EXPORT'
    skipped=next(record for record in manifest['skipped'] if record['path'].endswith('/analysis.json'))
    assert skipped['original_bytes'] > 32 * 1024 ** 2 and skipped['sha256']
    assert skipped['compact_equivalent']=='analysis_summary.json'
    write_json(analysis/'analysis_summary.json',{'counts':{'words':1},'analysis_status':'partial'})
    _,manifest=module.build_analysis_package(tmp_path,analysis,tmp_path/'packages','with',32,250,False,0)
    assert 'analysis.json' not in manifest['missing_essential_artifacts']
    assert 'analysis_summary.json' in manifest['compact_projections_used']


